@FunctionalInterface
interface Hitung {
    int jalankan(int a, int b);

    default int dobel(int a) {
        return jalankan(a, a);
    }
}

public class Main {
    public static void main(String[] args) {
        Hitung h = (a, b) -> {
            int c = a + b;
            return c * 2;
        };
        System.out.println(h.jalankan(2, 3));
    }
}

