import java.util.function.Supplier;

public class Main {
    public static void main(String[] args) {
        log(false, () -> mahal());
        log(true, () -> mahal());
        log(false, () -> mahal());
        System.out.println("dihitung: " + hitung);
    }

    static int hitung = 0;

    static String mahal() {
        hitung++;
        return "laporan";
    }

    static void log(boolean aktif, Supplier<String> pesan) {
        if (aktif) {
            System.out.println(pesan.get());
        }
    }
}

