import java.util.Optional;

public class Main {
    public static void main(String[] args) {
        Optional<String> o = Optional.of("ada");
        String a = o.orElse(cadangan());
        String b = o.orElseGet(() -> cadangan());
        System.out.println(a + " " + b + " " + hitung);
    }

    static int hitung = 0;

    static String cadangan() {
        hitung++;
        return "cadangan";
    }
}
